  int<lower=0> K;
  int<lower=0> ID2[N];
  real y[N];
}

parameters {
  real u[K];
  real b0;
  real<lower=0> mu_sigmasq;

  real<lower=0> res_sigmasq[K]; // random standard deviation

  real<lower=0> shape;
  real<lower=0> rate;
}

transformed parameters {
